def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0.0, min(budget, 8.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    slots = int(supply // WATER_REQ)
    contested = len(alive) + 1 > slots

    if hp <= 2 or no_water_days >= 2:
        emergency = max(95.0, highest_prev + 6.0)
        if budget < emergency:
            return max(0.0, budget)
        return min(budget, emergency)

    if hp <= 4 or no_water_days >= 1:
        strong = max(72.0, min(118.0, highest_prev + 3.0))
        return max(0.0, min(budget, strong))

    if highest_prev >= 140:
        bid = 18.0
    elif highest_prev >= 105:
        bid = 26.0
    elif highest_prev >= 80:
        bid = min(88.0, highest_prev + 2.0)
    elif highest_prev > 0:
        bid = max(32.0, avg_prev + 2.0)
    else:
        bid = 24.0

    if contested:
        bid += 4.0
    if urgent_opp >= 2:
        bid += 6.0
    elif urgent_opp == 1:
        bid += 3.0
    if rich_opp >= 2:
        bid -= 3.0

    if day >= 8 and hp >= 6:
        bid -= 4.0

    reserve = DAILY_SALARY * max(0, 10 - int(day))
    soft_cap = budget if budget <= reserve else max(0.0, budget - reserve * 0.15)
    bid = min(bid, soft_cap)

    if bid < 0:
        bid = 0.0
    return max(0.0, min(budget, float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_amount = 0.0

    is_critical_hp = my_status['hp'] <= 3
    is_late_game_desperation = day_context['day'] >= 8 and my_status['hp'] <= 5

    if is_critical_hp or is_late_game_desperation:
        bid_amount = DAILY_SALARY + 10.0 # Aggressively bid above salary, reacting to Alex's max bid
    else:
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * 0.95: # Opponents very aggressive, conserve budget
                bid_amount = DAILY_SALARY * 0.4
            else:
                # Bid competitively, slightly above previous high or a solid base
                bid_amount = max(DAILY_SALARY * 0.7, highest_prev_bid + 5.0)
        else:
            # No previous bids, bid moderately high to establish presence in a competitive scenario
            bid_amount = DAILY_SALARY * 0.8

    return min(my_status['budget'], bid_amount)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_max_bid = 0.0
    yesterday_min_bid = float('inf')
    yesterday_bid_list = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and isinstance(prev.get('bid'), (int, float)):
            bid = prev['bid']
            yesterday_bid_list.append(bid)
            if bid > yesterday_max_bid:
                yesterday_max_bid = bid
            if bid < yesterday_min_bid:
                yesterday_min_bid = bid
    if not yesterday_bid_list:
        # No information: bid moderately based on urgency
        if my_hp <= 2:
            return min(my_budget, DAILY_SALARY * 0.7)
        else:
            return min(my_budget, DAILY_SALARY * 0.4)
    # Exploit: if someone bid very high yesterday, they likely lost HP
    # If the highest bid was > 120, they might be weak; bid low to save
    # If the highest bid was moderate, bid slightly above it to secure water
    # If my HP is low, be aggressive
    if my_hp <= 2:
        target = min(my_budget, max(DAILY_SALARY * 0.8, yesterday_max_bid + 5))
        return target
    elif my_hp <= 4:
        # Medium health: bid around the second highest yesterday
        sorted_bids = sorted(yesterday_bid_list, reverse=True)
        if len(sorted_bids) >= 2:
            second_highest = sorted_bids[1]
        else:
            second_highest = sorted_bids[0]
        target = min(my_budget, max(DAILY_SALARY * 0.5, second_highest + 2))
        return target
    else:
        # High HP: exploit high yday bidders by saving budget
        if yesterday_max_bid > DAILY_SALARY * 0.85:
            return min(my_budget, DAILY_SALARY * 0.3)
        else:
            # Competitive: bid just above the minimum yesterday to win cheaply
            return min(my_budget, max(DAILY_SALARY * 0.2, yesterday_min_bid + 1))
